-- The workspace layout of a .shapr project (tables and indexes), as observed in files we made; no data.
CREATE TABLE "BrokenCurveIDToSourceName" ( "SketchID" INTEGER NOT NULL, "CurveID" INTEGER PRIMARY KEY NOT NULL, "NameID" BIGINT NOT NULL, FOREIGN KEY ("NameID") REFERENCES "HistoryNames" ("NameID") ON DELETE CASCADE, FOREIGN KEY ("CurveID") REFERENCES "SketchCurves" ("CurveID") ON DELETE CASCADE, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "ConstraintPointProperties" ( "SketchID" INTEGER PRIMARY KEY NOT NULL, "Data" BLOB, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "ConstraintVisualMementos" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ConstraintID" BLOB NOT NULL, "SketchID" INTEGER NOT NULL, "Data" BLOB, UNIQUE ("ConstraintID"), FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "Constraints" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ConstraintID" BLOB NOT NULL, "SketchID" INTEGER NOT NULL, "Data" BLOB, "IsBroken" BOOL NOT NULL, UNIQUE ("ConstraintID"), FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "ConstraintsToMissingReferencePoints" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ConstraintDescriptorID" BIGINT NOT NULL, "ManagedPointNameID" BIGINT NOT NULL, "PointID" INTEGER NOT NULL, "SketchID" INTEGER NOT NULL, UNIQUE ("ConstraintDescriptorID", "ManagedPointNameID"), FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE, FOREIGN KEY ("ManagedPointNameID") REFERENCES "HistoryNames" ("NameID") ON DELETE CASCADE, FOREIGN KEY ("ConstraintDescriptorID") REFERENCES "HistorySketchConstraints" ("DescriptorID") ON DELETE CASCADE );
CREATE TABLE "ConstructionSketches" ( "SketchID" INTEGER PRIMARY KEY NOT NULL, "ConstructionCurves" BLOB, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "DrawingNameRemapping" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "DrawingID" BIGINT NOT NULL, "PreHistoryCollapseNameID" BIGINT NOT NULL, "PostHistoryCollapseNameID" BIGINT, UNIQUE ("DrawingID", "PreHistoryCollapseNameID", "PostHistoryCollapseNameID"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "DrawingViewToBodyAssociations" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "BodyNameID" BIGINT NOT NULL, "ViewBodyIndex" INT NOT NULL, "IsOutdated" BOOL, UNIQUE ("DrawingID", "ViewID", "BodyNameID"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "Drawings" ( "DrawingID" INTEGER PRIMARY KEY NOT NULL, "Title" VARCHAR, "Created" DOUBLE, "LastChanged" DOUBLE, "ResourceID" VARCHAR, "ProjectedBodies" BLOB NOT NULL );
CREATE TABLE "HistoryFolders" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "FolderID" BLOB NOT NULL, "FolderName" BLOB, "Hidden" BOOL, "NamedChildren" BLOB, UNIQUE ("FolderID") );
CREATE TABLE "HistoryImportedBodies" ( "ImportedBodyID" INTEGER PRIMARY KEY NOT NULL, "ImportedPrototypeID" BIGINT NOT NULL, "Transform" BLOB NOT NULL, FOREIGN KEY ("ImportedPrototypeID") REFERENCES "HistoryImportedPrototypes" ("ImportedPrototypeID") ON DELETE CASCADE );
CREATE TABLE "HistoryImportedPrototypes" ( "ImportedPrototypeID" INTEGER PRIMARY KEY NOT NULL, "BodyData" BLOB NOT NULL );
CREATE TABLE "HistoryManagedSketchCurves" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "NameID" BIGINT NOT NULL, "SketchID" INTEGER NOT NULL, "CurveType" INT NOT NULL, "MaterializedCurves" BLOB, "IsConstructionSketch" BOOL NOT NULL, UNIQUE ("SketchID", "NameID"), FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE, FOREIGN KEY ("NameID") REFERENCES "HistoryNames" ("NameID") ON DELETE CASCADE );
CREATE TABLE "HistoryManagedSketchPoints" ( "ManagedPointID" INTEGER PRIMARY KEY NOT NULL, "SketchID" INTEGER NOT NULL, "Type" INT NOT NULL, "MaterializedPointID" BIGINT, "Data" BLOB NOT NULL, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "HistoryNameAnchoringPoints" ( "AnchoredNameID" INTEGER PRIMARY KEY NOT NULL, "HistoryTreeNodeID" BIGINT, FOREIGN KEY ("AnchoredNameID") REFERENCES "HistoryNames" ("NameID") ON DELETE CASCADE );
CREATE TABLE "HistoryNames" ( "NameID" INTEGER PRIMARY KEY NOT NULL, "Type" INT NOT NULL, "Data" BLOB NOT NULL, "Version" INT NOT NULL );
CREATE TABLE "HistorySketchConstraints" ( "DescriptorID" INTEGER PRIMARY KEY NOT NULL, "SketchID" INTEGER NOT NULL, "ConstraintType" INT NOT NULL, "MaterializedOrBrokenConstraintID" BLOB, "Data" BLOB NOT NULL, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "HistorySketchDescriptorOrder" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "OrderID" BIGINT NOT NULL, "SketchID" INTEGER NOT NULL, "ConstraintDescriptorID" BIGINT, "PointCoincidenceDescriptorID" BIGINT, UNIQUE ("SketchID", "OrderID"), FOREIGN KEY ("PointCoincidenceDescriptorID") REFERENCES "HistorySketchPointCoincidences" ("DescriptorID") ON DELETE CASCADE, FOREIGN KEY ("ConstraintDescriptorID") REFERENCES "HistorySketchConstraints" ("DescriptorID") ON DELETE CASCADE, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "HistorySketchPointCoincidences" ( "DescriptorID" INTEGER PRIMARY KEY NOT NULL, "SketchID" INTEGER NOT NULL, "MaterializedPointID" BIGINT, "Data" BLOB NOT NULL, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "HistoryTreeNodes" ( "HistoryTreeNodeID" INTEGER PRIMARY KEY NOT NULL, "HistoryTreeNodeType" BIGINT NOT NULL, "Properties" BLOB NOT NULL );
CREATE TABLE "ImageShapes" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ShapeID" BLOB NOT NULL, "ShapeData" BLOB, "ImageShapeName" BLOB, "OrderInList" INT, "ImageID" BLOB, UNIQUE ("ShapeID"), FOREIGN KEY ("ImageID") REFERENCES "Images" ("ImageID") ON DELETE CASCADE );
CREATE TABLE "Images" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ImageID" BLOB NOT NULL, "ImageData" BLOB, UNIQUE ("ImageID") );
CREATE TABLE "IsolatedElements" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "Type" INT, "ItemID" BLOB NOT NULL, UNIQUE ("Type", "ItemID") );
CREATE TABLE "MaterialDefinitions" ( "DefinitionID" INTEGER PRIMARY KEY NOT NULL, "Name" VARCHAR NOT NULL, "ShaderType" INT NOT NULL, "CanChangeBaseColor" BOOL NOT NULL, "CanChangeScale" BOOL NOT NULL, "Attributes" BLOB NOT NULL, "BaseColorTexture" BIGINT, "NormalTexture" BIGINT, "RoughnessTexture" BIGINT, "MetallicTexture" BIGINT, "SheenRoughnessTexture" BIGINT, "ClearCoatRoughnessTexture" BIGINT, "ClearCoatNormalTexture" BIGINT, "IORTexture" BIGINT, "TransmissionTexture" BIGINT, "OcclusionTexture" BIGINT, FOREIGN KEY ("OcclusionTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("TransmissionTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("IORTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("ClearCoatNormalTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("ClearCoatRoughnessTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("SheenRoughnessTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("MetallicTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("RoughnessTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("NormalTexture") REFERENCES "MaterialTextures" ("TextureID"), FOREIGN KEY ("BaseColorTexture") REFERENCES "MaterialTextures" ("TextureID") );
CREATE TABLE "MaterialInstances" ( "InstanceID" INTEGER PRIMARY KEY NOT NULL, "DefinitionID" BIGINT NOT NULL, "Properties" BLOB );
CREATE TABLE "MaterialTextures" ( "TextureID" INTEGER PRIMARY KEY NOT NULL, "Data" BLOB NOT NULL );
CREATE TABLE "MaterializedCurveNameToCurveID" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "SketchID" INTEGER NOT NULL, "NameID" BIGINT NOT NULL, "CurveID" INTEGER NOT NULL, UNIQUE ("SketchID", "NameID"), FOREIGN KEY ("NameID") REFERENCES "HistoryNames" ("NameID") ON DELETE CASCADE, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "MaterializedPointNameToPointID" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "SketchID" INTEGER NOT NULL, "NameID" BIGINT NOT NULL, "PointID" INTEGER NOT NULL, UNIQUE ("SketchID", "NameID"), FOREIGN KEY ("NameID") REFERENCES "HistoryNames" ("NameID") ON DELETE CASCADE, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "Metadata" ( "MetadataID" INTEGER PRIMARY KEY NOT NULL, "MetadataTypeID" INT NOT NULL, "Data" BLOB NOT NULL );
CREATE TABLE "MetadataAssignments" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "NameID" BIGINT NOT NULL, "MetadataID" BIGINT NOT NULL, UNIQUE ("NameID", "MetadataID") );
CREATE TABLE "MissingReferenceNamesToCurves" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "DescriptorID" BIGINT NOT NULL, "NameID" BIGINT NOT NULL, "CurveID" INTEGER NOT NULL, "SketchID" INTEGER NOT NULL, UNIQUE ("DescriptorID", "NameID"), FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE, FOREIGN KEY ("CurveID") REFERENCES "SketchCurves" ("CurveID") ON DELETE CASCADE, FOREIGN KEY ("NameID") REFERENCES "HistoryNames" ("NameID") ON DELETE CASCADE, FOREIGN KEY ("DescriptorID") REFERENCES "HistorySketchConstraints" ("DescriptorID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceAnnotationGeometries" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "AnnotationGeometryID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "Type" TINYINT NOT NULL, "AdditionalData" BLOB NOT NULL, UNIQUE ("DrawingID", "AnnotationGeometryID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceBaseViews" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ViewID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "CustomBaseViewTransform" BLOB, UNIQUE ("DrawingID", "ViewID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceDetailCircles" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "DetailCircleID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "Geometry" BLOB NOT NULL, UNIQUE ("DrawingID", "DetailCircleID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceDetailViews" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ViewID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "DefiningViewProjectionPlane" BLOB NOT NULL, UNIQUE ("DrawingID", "ViewID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceDimensions" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "DimensionID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "Type" TINYINT NOT NULL, "LabelPosition" BLOB, "LabelProperties_PrefixText" TEXT, "LabelProperties_SuffixText" TEXT, "LabelProperties_TolerancesData" BLOB NOT NULL, "AdditionalData" BLOB NOT NULL, UNIQUE ("DrawingID", "DimensionID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceHatches" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "HatchID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "Contours" BLOB NOT NULL, "PatternAngle" DOUBLE NOT NULL, UNIQUE ("DrawingID", "HatchID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceImageItems" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ImageItemID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "ImageTextureID" BIGINT NOT NULL, "Frame" BLOB NOT NULL, UNIQUE ("DrawingID", "ImageItemID"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE, FOREIGN KEY ("DrawingID", "ImageTextureID") REFERENCES "PaperspaceImageTextures" ("DrawingID", "ImageTextureID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceImageTextures" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ImageTextureID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "Texture" BLOB NOT NULL, "Width" BIGINT NOT NULL, "Height" BIGINT NOT NULL, UNIQUE ("DrawingID", "ImageTextureID"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceLeaders" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "LeaderID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, UNIQUE ("DrawingID", "LeaderID"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceObjectAssociations" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "DrawingID" BIGINT NOT NULL, "ObjectID" BIGINT NOT NULL, "AssociateID" BIGINT NOT NULL, "AssociateIndex" TINYINT NOT NULL, UNIQUE ("DrawingID", "ObjectID", "AssociateIndex"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "PaperspacePointRoles" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "PointID" INTEGER NOT NULL, "DrawingID" BIGINT NOT NULL, "Role" TINYINT NOT NULL, "RelatedObjectID" BIGINT NOT NULL, UNIQUE ("DrawingID", "Role", "RelatedObjectID"), FOREIGN KEY ("DrawingID", "PointID") REFERENCES "PaperspacePoints" ("DrawingID", "PointID") ON DELETE CASCADE );
CREATE TABLE "PaperspacePoints" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "PointID" INTEGER NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "Position" BLOB NOT NULL, UNIQUE ("DrawingID", "PointID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceProjectedCurves" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "CurveID" INTEGER NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "Geometry" BLOB NOT NULL, "CurveSourceContext" BLOB, "ClippingType" TINYINT NOT NULL, "IsDrafted" BOOL NOT NULL, UNIQUE ("DrawingID", "CurveID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceProjectedViews" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ViewID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "ParentView" BIGINT NOT NULL, "IsUsingParentScale" BOOL NOT NULL, UNIQUE ("DrawingID", "ViewID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceSectionLines" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "SectionLineID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "ViewID" BIGINT NOT NULL, "ControlPoints" BLOB NOT NULL, "DefiningSegmentIndex" BIGINT NOT NULL, "IsBound" BOOLEAN NOT NULL, UNIQUE ("DrawingID", "SectionLineID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceSectionViews" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ViewID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "DefiningViewProjectionPlane" BLOB NOT NULL, "CenterOffset" BLOB, "IsUsingParentScale" BOOL NOT NULL, UNIQUE ("DrawingID", "ViewID"), FOREIGN KEY ("DrawingID", "ViewID") REFERENCES "PaperspaceViews" ("DrawingID", "ViewID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceSheetPreferences" ( "DrawingID" INTEGER PRIMARY KEY NOT NULL, "Orientation" INT NOT NULL, "Scale" INT NOT NULL, "Size" INT NOT NULL, "LinearDimension_Unit" INT NOT NULL, "LinearDimension_FormatType" INT NOT NULL, "LinearDimension_Precision" INT NOT NULL, "AngularDimension_FormatType" INT NOT NULL, "AngularDimension_Precision" INT NOT NULL, "TitleBlockTemplate" INT NOT NULL, "IsBorderVisible" BOOL NOT NULL, "IsTitleBlockVisible" BOOL NOT NULL, "Projection" INT NOT NULL, "DecimalSeparator" INT NOT NULL, "ThousandSeparator" INT NOT NULL, "VisibleOutlinesWidth" INT NOT NULL, "HiddenLinesWidth" INT NOT NULL, "DimensionLinesWidth" INT NOT NULL, "CenterlinesWidth" INT NOT NULL, "SectionLinesWidth" INT NOT NULL, "DetailMarksLineWidth" INT NOT NULL, DateFormat INT NOT NULL, FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceTexts" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "TextID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "Type" INT NOT NULL, "RawText" VARCHAR, "Placement" BLOB NOT NULL, "VerticalAnchor" INT NOT NULL, "HorizontalAnchor" INT NOT NULL, UNIQUE ("DrawingID", "TextID"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "PaperspaceViews" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ViewID" BIGINT NOT NULL, "DrawingID" BIGINT NOT NULL, "Orientation" BLOB NOT NULL, "Name" VARCHAR NOT NULL, "Scale" BLOB NOT NULL, "CenterOnSheet" BLOB NOT NULL, "IsDraftedLayerVisible" BOOL NOT NULL, UNIQUE ("DrawingID", "ViewID"), FOREIGN KEY ("DrawingID") REFERENCES "Drawings" ("DrawingID") ON DELETE CASCADE );
CREATE TABLE "PersistedCalls" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "CallKey" BLOB NOT NULL, "CallData" BLOB NOT NULL, UNIQUE ("CallKey") );
CREATE TABLE "PersistentMeasurements" ( "MeasurementID" INTEGER PRIMARY KEY NOT NULL, "MeasurementData" BLOB NOT NULL );
CREATE TABLE "Settings" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "SettingName" BLOB NOT NULL, "SettingValue" BLOB, UNIQUE ("SettingName") );
CREATE TABLE "Shapes" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "ShapeID" BLOB NOT NULL, "ShapeData" BLOB, "Hidden" BOOL, "ShapeName" BLOB, UNIQUE ("ShapeID") );
CREATE TABLE "SketchControllers" ( "SketchID" INTEGER PRIMARY KEY NOT NULL, "Name" BLOB, "IsHidden" BOOL, "OrderInList" INT, "PlaneCenterX" DOUBLE, "PlaneCenterY" DOUBLE, "PlaneCenterZ" DOUBLE, "PlaneNormX" DOUBLE, "PlaneNormY" DOUBLE, "PlaneNormZ" DOUBLE, "PlaneUDirX" DOUBLE, "PlaneUDirY" DOUBLE, "PlaneUDirZ" DOUBLE );
CREATE TABLE "SketchCurveSuccessors" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "CurveID" INTEGER NOT NULL, "SuccessorIndex" INT NOT NULL, "SuccessorCurveID" BIGINT NOT NULL, UNIQUE ("CurveID", "SuccessorIndex") );
CREATE TABLE "SketchCurves" ( "CurveID" INTEGER PRIMARY KEY NOT NULL, "SketchID" INTEGER NOT NULL, "Data" BLOB, "IsMissingReference" BOOL NOT NULL, "ManagedCurveType" INT, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "SketchPatternCurveTracking" ( "SketchID" INTEGER NOT NULL, "CurveID" INTEGER PRIMARY KEY NOT NULL, "ConstraintDescriptorID" BIGINT NOT NULL, "SourceCurveID" BIGINT NOT NULL, "PatternTracking" BLOB NOT NULL, FOREIGN KEY ("ConstraintDescriptorID") REFERENCES "HistorySketchConstraints" ("DescriptorID") ON DELETE CASCADE, FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "StandaloneConstraintPoints" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "PointID" INTEGER NOT NULL, "SketchID" INTEGER NOT NULL, "Data" BLOB, "Type" INT NOT NULL, UNIQUE ("SketchID", "PointID"), FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "Symbols" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "SymbolID" BLOB NOT NULL, "SketchID" INTEGER NOT NULL, "Data" BLOB, UNIQUE ("SymbolID"), FOREIGN KEY ("SketchID") REFERENCES "SketchControllers" ("SketchID") ON DELETE CASCADE );
CREATE TABLE "VisualEnvironmentInstances" ( "InstanceID" INTEGER PRIMARY KEY NOT NULL, "DefinitionID" BIGINT NOT NULL, "Properties" BLOB );
CREATE TABLE Decals( DecalID INTEGER NOT NULL PRIMARY KEY, Name VARCHAR NOT NULL, Attributes BLOB NOT NULL, Asset BLOB NOT NULL);
CREATE TABLE DecalInstances( InstanceID INTEGER NOT NULL PRIMARY KEY, DefinitionID INTEGER NOT NULL, Attributes BLOB NOT NULL, FOREIGN KEY(DefinitionID) REFERENCES Decals(DecalID));
CREATE TABLE BodyRevisionBlocks( PartitionID INTEGER NOT NULL, ChunkIndex INTEGER NOT NULL, Block BLOB, Phase INTEGER NOT NULL DEFAULT 0, IsDeleted BOOL NOT NULL DEFAULT 0, PRIMARY KEY (PartitionID, ChunkIndex, Phase) );
CREATE TABLE BodyRevisionDeltas( PartitionID INTEGER NOT NULL, ChunkIndex INTEGER NOT NULL, Delta BLOB, Phase INTEGER NOT NULL DEFAULT 0, IsDeleted BOOL NOT NULL DEFAULT 0, PRIMARY KEY (PartitionID, ChunkIndex, Phase) );
CREATE TABLE "HistoryMissingNamedTopologies" ( "RowID" INTEGER PRIMARY KEY NOT NULL, "HistoryTreeNodeID" BIGINT NOT NULL, "NameID" BIGINT NOT NULL, "BodyData" BLOB NOT NULL, UNIQUE ("HistoryTreeNodeID", "NameID") );
CREATE INDEX PaperspacePointRolesPointIndex ON PaperspacePointRoles(PointID, DrawingID);
